window.LOR_VERIFY = {"cv": "1023_1", "checked": "23.10.2026", "pdf": "1023_1_Коклюш у детей.pdf", "pages": 59, "items": {"ma37": {"s": "ok", "sec": "1.4", "page": 12, "q": "Классификация коклюша по МКБ 10: А37"}, "ma370": {"s": "ok", "sec": "1.4", "page": 12, "q": "А37.0 Коклюш, вызванный Bordetella pertussis;"}, "ma371": {"s": "ok", "sec": "1.4", "page": 12, "q": "А37.1 Коклюш, вызванный Bordetella parapertussis;"}, "ma378": {"s": "ok", "sec": "1.4", "page": 12, "q": "А37.8 Коклюш, вызванный другим уточненным возбудителем вида Bordetella;"}, "ma379": {"s": "ok", "sec": "1.4", "page": 12, "q": "А37.9 Коклюш неуточненный."}, "s1": {"s": "ok", "sec": "1.1", "page": 8, "q": "Коклюш (Pertussis) - острое антропонозное инфекционное заболевание, вызываемое бактериями рода Bordetella, преимущественно Bordetella pertussis, передающееся воздушно- капельным путем, характеризующееся длительным приступообразным судорожным (спазматическим) кашлем, поражением дыхательной, сердечно-сосудистой и нервной систем."}, "s-sus": {"s": "ok", "sec": "2.1", "page": 14, "q": "целенаправленно выявить жалобу на кашель длительностью более 7 дней, с уточнением его характера (сухой навязчивый или приступообразный кашель, заканчивающийся рвотой)", "note": "Температура и интоксикация — там же, комментарий о температуре тела; течение кашля — раздел 1.6."}, "s-lab": {"s": "ok", "sec": "2.3", "page": 18, "q": "ПЦР следует применять с диагностической целью однократно, как пациентам с клиническими симптомами коклюша, детям и взрослым, кашляющим более 7, но не более 28-35 дней", "note": "ИФА — «пациентам, кашляющим три и более недели»."}, "s-abx": {"s": "ok", "sec": "3.1", "page": 23, "q": "Антибактериальная терапия рекомендована для лечения коклюша с целью эрадикации возбудителя у пациентов первого года жизни, обратившихся за медицинской помощью в течение 6 недель от начала заболевания, пациентам других возрастных категорий, обратившихся в течение 3 недель от начала заболевания. Антибактериальная терапия уменьшает колонизацию B.pertussis и контагиозность коклюша, что особенно актуально в ранние сроки заболевания, однако не влияет на выраженность и длительность симптомов заболевания"}, "s-icu": {"s": "ok", "sec": "6", "page": 36, "q": "Показания для перевода в отделение реанимации и интенсивной терапии [36,69,66]. • брадикардия или кашлевой пароксизм, который вызывает десатурацию до SpO2 <90%; • цианоз, вялость, выраженная бледность; • любое апноэ > 15 секунд у младенца или > 10 секунд у новорожденного; • апноэ любой продолжительности, если оно вызывает десатурацию (цианоз лица, акроцианоз); • любая другая прогрессирующая дыхательная недостаточность, приводящая к тяжелой респираторной недостаточности или SpO2 <90%; • угнетение сознания; • судороги • подозрение на отек головного мозга."}, "s-ent": {"s": "ok", "sec": "Прил. Г2", "page": 59, "q": "Геморрагический синдром: кровотечения (из носа, заднеглоточного пространства, бронхов, наружного слухового прохода), кровоизлияния (в головной мозг, в кожу и слизистые оболочки, склеру и сетчатку, головной и спинной мозг); • Связанные с перенапряжением мышц брюшной стенки и повышением внутрибрюшного давления: грыжи (пупочная, паховая), выпадение слизистой оболочки прямой кишки; • Разрывы барабанной перепонки и диафрагмы.", "note": "Отит — неспецифические осложнения, там же."}, "c-def": {"s": "ok", "sec": "1.1", "page": 8, "q": "Коклюш (Pertussis) - острое антропонозное инфекционное заболевание, вызываемое бактериями рода Bordetella, преимущественно Bordetella pertussis, передающееся воздушно- капельным путем, характеризующееся длительным приступообразным судорожным (спазматическим) кашлем, поражением дыхательной, сердечно-сосудистой и нервной систем."}, "c-repr": {"s": "ok", "sec": "Термины", "page": 7, "q": "Репризы - звучные судорожные вдохи, возникающие при прохождении воздуха через суженную вследствие ларингоспазма голосовую щель"}, "c-etio": {"s": "ok", "sec": "1.2", "page": 8, "q": "Этиология. Возбудитель коклюша (Bordetella pertussis) - грамотрицательная гемолитическая палочка, неподвижная, не образующая капсул и спор, неустойчивая во внешней среде. Другие бордетеллы (Bordetella parapertussis, редко Bordetella bronchiseptica) также вызывают коклюшеподобное заболевание (клинический коклюш). Bordetella bronchiseptica чаще вызывает бордетеллезы у животных [1-4, 24]. В последние годы изучают роль Bordetella holmesii как причины коклюшеподобных заболеваний в связи с созданием тест-системы для ее выявления [85,86]. Коклюшная палочка образует экзотоксин (коклюшный токсин, лимфоцитоз-стимулирующий или гистамин-сенсибилизирующий фактор), имеющий основное значение в патогенезе и обладающий системным воздействием (гематологическое и иммуносупрессивное)."}, "c-colon": {"s": "ok", "sec": "1.2", "page": 10, "q": "Одной из причин длительного сохранения кашля является формирование гиперреактивности бронхов на фоне длительной колонизации носоглотки детей Bordetella pertussis, что может стать причиной формирования бронхиальной астмы у реконвалесцентов коклюша и обострения текущего заболевания [5, 6]. Возможная длительность колонизации более 3 и до 6 месяцев, выявленная у реконвалесцентов коклюша и контактных лиц в семейных очагах, обусловлена способностью Bordetella pertussis переходить в авирулентное фазовое состояние за счет мутаций в гене вирулентности bvg AS, в частности внедрения мобильных генетических элементов IS481 в специфический сайт оперона bvg AS [7, 8]."}, "c-epi": {"s": "ok", "sec": "1.3", "page": 11, "q": "Риск инфицирования для окружающих особенно велик в предсудорожном периоде заболевания и начале периода судорожного кашля, далее постепенно снижается. К 25 дню от начала заболевания больной, как правило, перестает быть заразным. При отсутствии антибактериальной терапии риск передачи инфекции непривитому ребенку, находящемуся в тесном контакте, сохраняется до 7-ой недели периода судорожного кашля. Особенно длительно выделяется возбудитель коклюша у детей раннего возраста [9]. Дети, получающие антибактериальные препараты, к которым чувствительна коклюшная палочка, считаются незаразными после 5 дней проведения антибактериальной терапии или окончания ее курса [10,11]."}, "c-epi-c": {"s": "ok", "sec": "1.3", "page": 11, "q": "При отсутствии антибактериальной терапии риск передачи инфекции непривитому ребенку, находящемуся в тесном контакте, сохраняется до 7-ой недели периода судорожного кашля."}, "c-epi2": {"s": "ok", "sec": "1.3", "page": 11, "q": "Восприимчивость к коклюшу высока: индекс контагиозности составляет до 70%- 100% у непривитых детей первого года жизни, особенно новорожденных и недоношенных.", "note": "Заболеваемость до 1 года, источники заражения младенцев, иммунитет 10–20 лет — там же, раздел 1.3."}, "c-class": {"s": "ok", "sec": "1.5", "page": 12, "q": "По типу формы заболевания: Типичные 12  Атипичные: - стертая; - бактерионосительство По степени тяжести: Легкая форма Среднетяжелая форма Тяжелая форма По характеру течения: Гладкое Негладкое: - с осложнениями; - с наслоением вторичной инфекции; - с обострением хронических заболеваний"}, "cl-typ": {"s": "ok", "sec": "1.6", "page": 13, "q": "Инкубационный период продолжается от 3 до 14 дней (в среднем 7-8 дней), реже может продлеваться до 21 дня. Для типичной формы коклюша характерно постепенное начало при нормальной температуре тела, отсутствие симптомов интоксикации, появление сухого навязчивого кашля, нарастающего в динамике. Разгар заболевания характеризуется приступообразным, судорожным кашлем, в ряде случаев, сопровождающимся свистящим вдохом через спазмированную голосовую щель - репризом, а также рвотой после кашля или отхождением вязкой стекловидной мокроты."}, "cl-mild": {"s": "ok", "sec": "1.6", "page": 13, "q": "При легкой степени тяжести число приступов судорожного кашля за сутки составляет 8-10; они непродолжительные. Рвоты не бывает, признаки кислородной недостаточности отсутствуют. Состояние больного удовлетворительное, самочувствие не нарушено, аппетит и сон сохранены. Изменения в анализе крови отсутствуют или количество лейкоцитов не превышает 10-15,0 х 109/л, содержание лимфоцитов — до 70%. Осложнений, как правило, не бывает."}, "cl-mod": {"s": "ok", "sec": "1.6", "page": 13, "q": "Среднетяжелая степень характеризуется возникновением приступов судорожного кашля до 15-20 раз в сутки, они продолжительные и выраженные. В конце приступа наблюдается отхождение вязкой густой слизи, мокроты и, нередко, рвоты. Общее состояние больных нарушается: дети капризные, вялые, плаксивые, раздражительные, неохотно вступают в контакт. Аппетит снижается, сон беспокойный, прерывистый. Во время приступа кашля появляется периоральный цианоз. Даже вне приступа кашля отмечаются одутловатость лица, отечность век, возможны кровоизлияния в 13  склеры. Может обнаруживаться характерный для коклюша симптом: надрыв или язвочка уздечки языка. Изменения в гемограмме выраженные: лейкоцитоз до 20-30 х109/л, лимфоцитоз — до 80%. Нередко возникают осложнения как специфического, так и неспецифического характера."}, "cl-sev": {"s": "ok", "sec": "1.6", "page": 14, "q": "При тяжелой степени число приступов судорожного кашля за сутки достигает 25-30 и более. Приступы тяжелые, продолжительные, как правило, заканчиваются рвотой, наблюдаются пароксизмы. Отмечаются резко выраженные признаки кислородной недостаточности — постоянный периоральный цианоз, акроцианоз, цианоз лица, бледность кожи. Наблюдаются одутловатость лица, пастозность век, нередко возникают геморрагии на коже шеи, плечевого пояса, возможны кровоизлияния в склеры. Резко нарушаются сон и аппетит, у детей первого года жизни возможно снижение веса. Больные становятся вялыми, раздражительными, адинамичными, плохо вступают в контакт. Обнаруживают характерный для коклюша симптом: надрыв или язвочку уздечки языка. Изменения в гемограмме резко выражены: лейкоцитоз достигает 40,0 х 109/л и более, лимфоцитоз — до 85% и более. Характерно возникновение угрожающих жизни осложнений (остановка или повторные задержки дыхания, нарушение мозгового кровообращения в виде внутричерепных кровоизлияний, судорог на фоне гипоксического отека мозга). Возможны неблагоприятные исходы болезни, вплоть до летальных."}, "cl-sev-note": {"s": "ok", "sec": "1.6", "page": 14, "q": "При определении тяжести коклюша основное значение имеют клинические критерии, однако выраженность гематологических изменений имеет вспомогательное значение при определении тяжести заболевания, протекающего как моноинфекция (Приложение Г1)"}, "g1-cyan": {"s": "ok", "sec": "Прил. Г1", "page": 58, "q": "Критерии оценки степени тяжести коклюша по клиническим признакам [2] Степень тяжести Признаки Легкая Среднетяжелая Тяжелая Цианоз лица при кашле"}, "g1-pre": {"s": "ok", "sec": "Прил. Г1", "page": 58, "q": "предсудорожного периода 10-14 дней 6-9 дней 3-5 дней"}, "g1-freq": {"s": "ok", "sec": "Прил. Г1", "page": 58, "q": "Частота приступов кашля Статус в межприступный период до 15 в сутки; репризы редко активный, аппетит сохранен 16-25 в сутки; репризы часто активный, аппетит снижен более 25 в сутки; пароксизмы"}, "g1-leuk": {"s": "ok", "sec": "Прил. Г1", "page": 58, "q": "Гематологические критерии оценки степени тяжести коклюша [59,60] Форма тяжести Показатели Легкая Среднетяжелая Тяжелая лейкоцитоз 10-15 х 109 кл/л до 20-30 х 109 кл/л более 40-50 х 109 кл/л"}, "g1-lymph": {"s": "ok", "sec": "Прил. Г1", "page": 58, "q": "более 40-50 х 109 кл/л лимфоцитоз до 70 % 70-80 % более 80 %"}, "cl-compl": {"s": "ok", "sec": "Прил. Г2", "page": 59, "q": "Приложение Г2. Осложнения коклюша [1,2,4] Специфические, обусловленные действием возбудителя • Поражения бронхолегочной системы (пневмония, ателектаз, эмфизема средостения); • Нарушения ритма дыхания (задержки дыхания — до 30 секунд и остановки — апноэ более 30 секунд); • Поражение ЦНС, обусловленное гипоксическим отеком мозга или кровоизлиянием в мозг: коклюшная энцефалопатия различной степени тяжести; • Геморрагический синдром: кровотечения (из носа, заднеглоточного пространства, бронхов, наружного слухового прохода), кровоизлияния (в головной мозг, в кожу и слизистые оболочки, склеру и сетчатку, головной и спинной мозг); • Связанные с перенапряжением мышц брюшной стенки и повышением внутрибрюшного давления: грыжи (пупочная, паховая), выпадение слизистой оболочки прямой кишки; • Разрывы барабанной перепонки и диафрагмы. Неспецифические осложнения обусловлены наслоением вторичной бактериальной микрофлоры (пневмония, бронхит, бронхиолит, лимфаденит, отит и др.)."}, "cl-apnea": {"s": "ok", "sec": "Прил. Г2", "page": 59, "q": "Апноэ при коклюше у детей первых месяцев жизни подразделяется на спазматическое и синкопальное. Спазматическое апноэ возникает во время приступа кашля, продолжается от 30 секунд до 1 минуты. Синкопальное апноэ, иначе называемое паралитическим, не связано с приступом кашля. Ребенок становится вялым, гипотоничным. Появляется сначала бледность, а затем цианоз кожных покровов. Наступает прекращение дыхания при сохранении сердечной деятельности. Подобные апноэ длятся 1 - 2 минуты."}, "cl-resid": {"s": "ok", "sec": "Прил. Г2", "page": 59, "q": "Резидуальные изменения. Хронические бронхолегочные заболевания (хронический бронхит, бронхоэктатическая болезнь); задержка психомоторного развития, невроз, судорожный синдром, различные речевые расстройства; энурез; редко у не привитых при отсутствии этиопатогенетической терапии — слепота, глухота, парезы, параличи."}, "d-crit": {"s": "ok", "sec": "2", "page": 14, "q": "Диагноз устанавливается на основании: эпидемиологических данных (контакт с больными коклюшем и кашляющими в окружении); клинической картины (длительный кашель, чаще приступообразный); данных о прививочном статусе и результатов лабораторной диагностики."}, "d-crit-one": {"s": "ok", "sec": "2.3", "page": 17, "q": "для подтверждения диагноза достаточно положительного результата одного из исследования."}, "d-cough": {"s": "ok", "sec": "2.1", "page": 14, "q": "Рекомендуется при сборе анамнеза и жалоб у пациентов при инфекционном заболевании, при подозрении на коклюш, целенаправленно выявить жалобу на кашель длительностью более 7 дней, с уточнением его характера (сухой навязчивый или приступообразный кашель, заканчивающийся рвотой) [1, 2, 17, 18,21] с целью уточнения клинической картины и дифференциальной"}, "d-cough-c": {"s": "ok", "sec": "2.1", "page": 15, "q": "Характер кашля зависит от сроков обращения пациента за медицинской помощью: в первые 7-14 дней он сухой навязчивый, в последующие дни от начала заболевания - приступообразный судорожный. На 2-3 неделях заболевания может присоединяться рвота после кашля. Уточняют, чем заканчивается кашель (рвотой, отхождением вязкой стекловидной мокроты), отмечаются ли репризы и цианоз лица во время приступа кашля, наличие задержек дыхания, судорог, эпизодов нарушения сознания. Устанавливают наличие динамики кашля: от сухого навязчивого до приступообразного судорожного. Отсутствие типичных приступов спазматического кашля не исключает атипичных форм заболевания у привитых (в течение предшествующих 3-4 лет) детей, а также подростков и взрослых, у которых могут отмечаться стертые формы коклюша. Наличие цианоза лица во время приступа кашля свидетельствует о тяжелой степени тяжести коклюша. Наличие репризов характерно для больных коклюшем и паракоклюшем, однако их отсутствие не исключает коклюша. Обращают внимание на наличие или отсутствие других катаральных симптомов (ринорея или заложенность носа, боль или першение в горле, осиплость голоса), наличие или отсутствие одышки."}, "d-cough-atyp": {"s": "ok", "sec": "2.1", "page": 15, "q": "Отсутствие типичных приступов спазматического кашля не исключает атипичных форм заболевания у привитых (в течение предшествующих 3-4 лет) детей, а также подростков и взрослых, у которых могут отмечаться стертые формы коклюша. Наличие цианоза лица во время приступа кашля свидетельствует о тяжелой степени тяжести коклюша. Наличие репризов характерно для больных коклюшем и паракоклюшем, однако их отсутствие не исключает коклюша."}, "d-contact": {"s": "ok", "sec": "2.1", "page": 15, "q": "уточнить наличие контактов с больным коклюшем или длительно кашляющим (более 3-4 недель) ребенком/взрослым с целью уточнения возможного источника инфицирования[10, 17, 18]. Уровень убедительности рекомендаций С (уровень достоверности доказательств - 5). Комментарии: Выясняют данные о наличие контактов с больными коклюшем или длительно кашляющими в семье, детском учреждении и ином окружении ребенка. При наличии контакта с больным, лабораторно подтвержденным коклюшем, у ранее не болевшего пациента с клинической картиной коклюшеподобного заболевания, можно диагностировать эпидемиологически связанный случай коклюша."}, "d-temp": {"s": "ok", "sec": "2.1", "page": 15, "q": "Рекомендуется у пациентов с подозрением на коклюш уточнить характеристику температуры тела в начале заболевания в целях проведения дифференциальной диагностики [2,4, 17, 18]. Уровень убедительности рекомендаций С (уровень достоверности доказательств - 5). Комментарии: Температура тела редко повышается в начальный (предсудорожный) 15  период коклюша, что помогает проведению дифференциальной диагностики, но может регистрироваться при наслоении сопутствующих респираторных вирусных инфекций или осложнений воспалительного характера в период разгара заболевания. Симптомы интоксикации (слабость, сонливость, снижение аппетита, головная боль) отсутствуют в течение всего периода заболевания в случаях его гладкого течения."}, "d-vacc": {"s": "ok", "sec": "2.1", "page": 16, "q": "Рекомендуется у всех пациентов с подозрением на коклюш при сборе анамнеза уточнить вакцинальный статус пациента с целью оценки прогноза течения заболевания [19, 20]. Уровень убедительности рекомендаций С (уровень достоверности доказательств -3). Комментарии: Наличие вакцинации против коклюша не исключает развития заболевания, однако исключает развитие заболевания в тяжелой форме."}, "d-skin": {"s": "ok", "sec": "2.2", "page": 16, "q": "у всех пациентов с подозрением на коклюш оценить состояние кожных покровов: с оценкой наличия или отсутствия периорального цианоза, отечности лица, век, наличие петехиальной сыпи на лице, кровоизлияний на склерах и коже век с целью оценки тяжести течения заболевания [4, 17, 20, 21]. Уровень убедительности рекомендаций С (уровень достоверности доказательств - 5). Комментарии: Наличие периорального цианоза, отечного и геморрагического синдромов свидетельствует о тяжелой или среднетяжелой степени коклюша и его негладкого течения. Наличие периорального цианоза в межприступный период и цианоза лица при кашле отражают выраженность гипоксии. Развитие отечного синдрома характеризуется также снижением диуреза, геморрагического синдрома - наличием носовых кровотечений на высоте кашля."}, "d-frenum": {"s": "ok", "sec": "2.2", "page": 16, "q": "у всех пациентов с подозрением на коклюш осмотр уздечки языка для выявления надрыва или язвочки [4, 17, 22,65 ]. Уровень убедительности рекомендаций С (уровень достоверности доказательств - 5). Комментарии: Наличие язвочки или надрыва уздечки языка является характерным для больных клиническим коклюшем симптомом, однако их отсутствие не исключает коклюш."}, "d-ausc": {"s": "ok", "sec": "2.2", "page": 17, "q": "Комментарии: В предсудорожном периоде коклюша хрипы не выслушиваются. В периоде судорожного кашля выслушивают жесткое дыхание, непостоянные грубые проводные хрипы. Постоянный характер хрипов при аускультации свидетельствует о развитии осложнений или наслоении сопутствующей инфекции. Бронхообструктивный синдром для больных моноинфекцией коклюша не характерен, его наличие свидетельствует о сочетанной этиологии заболевания (коклюшно-вирусной или коклюшно-микоплазменной). Типично различие аускультативной характеристики до и после приступа судорожного (спазматического) кашля (резкое уменьшение количества хрипов или их исчезновение). Очаговая симптоматика для коклюша не характерна и свидетельствует о развитии осложнений (пневмонии)."}, "d-oak": {"s": "ok", "sec": "2.3", "page": 17, "q": "Рекомендуется всем пациентам с подозрением на коклюш проведение общего (клинического) анализа крови развернутого с целью оценки тяжести заболевания[17, 21- 24, 59-60]. Уровень убедительности рекомендаций С (уровень достоверности доказательств - 4). Комментарии: В общем (клиническом) анализе крови у пациента, подозрительного на коклюш, выявление лейкоцитоза за счет лимфоцитоза на фоне нормального уровня скорости оседания эритроцитов (СОЭ) свидетельствует в пользу диагноза коклюш."}, "d-oak-c": {"s": "ok", "sec": "2.3", "page": 17, "q": "Отсутствие характерных гематологических изменений у длительно кашляющего пациента, подозрительного на коклюш, не может исключать клинический диагноз коклюш. Появление воспалительных изменений в гемограмме (нейтрофилез, лейкоцитарный сдвиг формулы в сторону юных форм, ускорение СОЭ) может отмечаться у больных коклюшем при развитии воспалительных, преимущественно неспецифических осложнений, а также сочетанных инфекций. При наличии лейкоцитоза общий (клинический) анализ крови необходимо выполнять в динамике до нормализации уровня лейкоцитов."}, "d-pcr": {"s": "ok", "sec": "2.3", "page": 17, "q": "пациентов с подозрением на коклюш определение ДНК возбудителей коклюша и коклюшеподобных заболеваний (Bordetella pertussis, Bordetella parapertussis, 17  Bordetella bronchiseprica) в мазках со слизистой оболочки носоглотки методом ПЦР (однократно) для подтверждения диагноза"}, "d-pcr-c": {"s": "ok", "sec": "2.3", "page": 18, "q": "Метод ПЦР позволяет обнаружить ДНК возбудителя как на ранних, так и поздних сроках, вплоть до 4-5 недели заболевания включительно, в том числе на фоне проведения антибиотикотерапии. Наличие в анамнезе вакцинации против коклюша не влияет на результаты ПЦР. Специфичность метода 85%-98%, чувствительность - 45%-65%. В ПЦР обнаруживается ДНК не только живых, но и погибших микробов, которые сохраняются в биологическом материале от 1 недели до 3-4 недель. В связи с этим ДНК может быть обнаружена на фоне клинического выздоровления и после успешного лечения антибиотиками, поэтому ПЦР не рекомендуется использовать для подтверждения эффективности лечения. ПЦР следует применять с диагностической целью однократно, как пациентам с клиническими симптомами коклюша, детям и взрослым, кашляющим более 7, но не более 28-35 дней; а также контактным детям и взрослым, работающим в детских учебных и лечебнопрофилактических учреждениях."}, "d-pcr-sens": {"s": "ok", "sec": "2.3", "page": 18, "q": "Специфичность метода 85%-98%, чувствительность - 45%-65%."}, "d-ifa": {"s": "ok", "sec": "2.3", "page": 18, "q": "Рекомендуется пациентам с подозрением на коклюш пациентам, кашляющим три и более недели, с целью подтверждения диагноза провести определение антител к возбудителю коклюша Bordetella pertussis в крови (серологическим методом исследования иммуноферментным анализом (ИФА)) [28-33]. Уровень убедительности рекомендаций С (уровень достоверности доказательств - 4). Комментарии: Методом иммуноферментного анализа определяют в крови антитела к возбудителю коклюша (Bordetella pertussis) класса IgM, IgA (в ранние сроки) и IgG (в поздние сроки болезни). Специфичность метода 89%, чувствительность 65%. Метод отличается большей чувствительностью, по сравнению с реакцией агглютинации (РА), в том числе у детей первых месяцев жизни, и позволяет выявлять антитела к отдельным антигенам возбудителя (коклюшному токсину, филаментозному агглютинину), что важно для контроля эффективности иммунизации бесклеточными вакцинами. Метод предпочтителен для диагностики коклюша у подростков и взрослых и на поздних сроках заболевания (более 4 недель)."}, "d-ifa-c": {"s": "ok", "sec": "2.3", "page": 18, "q": "При выявлении титров антител класса IgG у лиц, привитых в течение последних 5-7 лет, диагноз коклюша может быть подтвержден на основании четырехкратного нарастания титров антител в динамике через 1014 дней или при выявлении Ig А и высоких титров IgG у лиц, привитых более 5 лет назад", "note": "Специфичность 89%, чувствительность 65% — там же."}, "d-cult": {"s": "ok", "sec": "2.3", "page": 18, "q": "Рекомендуется провести двукратное микробиологическое (культуральное) исследование слизи с задней стенки глотки на палочку коклюша (Bordetella pertussis) пациентам с подозрением на коклюш и при наличии кашля не более 14-21 дня с целью подтверждения диагноза и проведения дифференциальной диагностики[1, 3, 10, 18, 25, 28, 85]. 18  Уровень убедительности рекомендаций С (уровень достоверности доказательств - 5). Комментарии: Микробиологическое (культуральное) исследование слизи с задней стенки глотки на палочку коклюша (Bordetella pertussis) проводится до начала антибактериальной терапии. Исследование с диагностической целью следует производить двукратно ежедневно или через день в ранние сроки заболевания (не позднее 3-ей недели болезни). (Забор материала необходимо проводить до еды или не ранее чем через два часа после еды)."}, "d-cult-c": {"s": "ok", "sec": "2.3", "page": 19, "q": "Специфичность метода 100%, чувствительность - 15% и менее. Метод до настоящего времени считают «золотым стандартом» для подтверждения коклюшной инфекции вследствие его высокой специфичности, но отрицательный результат исследования не исключает диагноза коклюш. К недостаткам метода относится отсроченное получение его результата."}, "d-viral": {"s": "ok", "sec": "2.3", "page": 19, "q": "Рекомендуется пациентам с негладким течением коклюша или при отсутствии эффекта от проводимой терапии с целью уточнения этиологии заболевания обследование на выявление возбудителей респираторных инфекций (ПЦР мазков из рото- или носоглотки): определение РНК вирусов парагриппа (Human Parainfluenza virus) в мазках со слизистой оболочки носоглотки методом ПЦР, определение РНК респираторно-синтициального вируса (Human Respiratory Syncytial virus) в мазках со слизистой оболочки ротоглотки методом ПЦР, определение РНК метапневмовируса (Human Metapneumovirus) в мазках со слизистой оболочки ротоглотки методом ПЦР, определение РНК риновирусов (Human Rhinovirus) в мазках со слизистой оболочки носоглотки методом ПЦР, определение ДНК аденовируса (Human Adenovirus) в мазках со слизистой оболочки ротоглотки методом ПЦР, молекулярно-биологическое исследование мазков со слизистой оболочки носоглотки на бокавирус (Human Bocavirus). Определение ДНК Chlamydophila pneumoniae в мазках со слизистой оболочки носоглотки методом ПЦР, Определение ДНК Chlamydophila pneumoniae в мазках со слизистой оболочки ротоглотки методом ПЦР, Определение ДНК Mycoplasma pneumoniae в мазках со слизистой оболочки носоглотки методом ПЦР, Определение ДНК Mycoplasma pneumoniae в мазках со слизистой оболочки ротоглотки методом ПЦР, Определение антител классов М, G (IgM, IgG) к микоплазме пневмонии (Mycoplasma pneumoniae) в крови, Определение антител к хламидии пневмонии (Chlamydophila pneumoniae) в крови [1, 2, 19, 61,]. Уровень убедительности рекомендаций С (уровень достоверности доказательств - 5). Комментарии: При негладком течении заболевания с повышением температуры тела, развитием или усилением катаральных симптомов (кроме кашля), появлении обструктивного 19  синдрома необходимо исключать сопутствующие инфекции, протекающие с коклюшеподобным синдромом или проводить с ними дифференциальную диагностику."}, "d-cmv": {"s": "ok", "sec": "2.3", "page": 20, "q": "Рекомендуется пациентам первого года жизни при тяжелом и негладком течении коклюша с целью выявления отягчающих факторов течения заболевания комплексное выявление маркеров активной цитомегаловирусной инфекции [74-76]: - определение антител класса M (IgM) к цитомегаловирусу (Cytomegalovirus) в крови ; - определение ДНК цитомегаловируса (Cytomegalovirus) методом ПЦР в периферической крови качественное/количественное исследование; - определение ДНК цитомегаловируса (Cytomegalovirus) в моче методом ПЦР, качественное/количественное исследование; - определение ДНК цитомегаловируса (Cytomegalovirus) в слюне или мазках из ротоглотки методом ПЦР (качественное/количественное исследование). Уровень убедительности рекомендаций В (уровень достоверности доказательств - 3). Комментарии: у больных коклюшем первого года жизни при тяжелом коклюше наличие анамнестических признаков риска врожденных инфекций (негладкое течение беременности и родов, недоношенность, низкая масса тела при рождении, недостаточноые прибавки массы тела в период первых месяцев жизни, затяжная желтуха новорожденных, а также появление на фоне заболевания коклюшем таких нехарактерных клинико-лабораторных проявлений, как: бронхообструктивного синдрома, умеренной гепатоспленомегалии, повышения аминотрансфераз (АЛТ, АСТ), признаков нефропатии (лейкоциты и/или эритроциты в моче), энтероколита легой степени тяжести (лейкоциты в кале) при отсутствии установленной кишечной инфекции необходимо исключить активацию или первичную манифестацию врожденной цитомегаловирусной инфекции. Активная цитомегаловирусная инфекция достоверно повышает риск тяжелого течения и неблагоприятного исхода."}, "d-xray": {"s": "ok", "sec": "2.4", "page": 20, "q": "Пациентам с подозрением на пневмонию рекомендуется проведение рентгенографии легких с целью уточнения диагноза [1, 2, 24, 34]. Уровень убедительности рекомендаций С (уровень достоверности доказательств - 5). Комментарии: Выполняется у пациентов с клинической картиной пневмонии или ателектаза (повышением температуры тела, появлением признаков интоксикационного синдрома, очаговой симптоматики в легких, одышки, тахипноэ, «стонущего» дыхания, учащение приступов"}, "d-ecg": {"s": "ok", "sec": "2.4", "page": 21, "q": "Пациентам с тяжелой степенью тяжести заболевания рекомендуется регистрация электрокардиограммы и эхокардиография с целью ранней диагностики кардиальных осложнений и легочной гипертензии [1, 2, 24, 34, 59, 60, 64, 77]. Уровень убедительности рекомендаций С (уровень достоверности доказательств -4). Комментарии: Целесообразно проводить пациентам с тяжелой степенью тяжести коклюша с целью ранней диагностики поражений сердца, или при наличии у них фоновых воспалительных заболеваний сердца или его пороков, а также при наличии тахикардии и/или аритмии."}, "d-eeg": {"s": "ok", "sec": "2.4", "page": 21, "q": "Пациентам с тяжелой степенью тяжести и негладким течением коклюша при декомпенсации фоновой неврологической патологии, при развитии судорог, признаках отека головного мозга на фоне течения коклюша рекомендуется проведение электроэнцефалографии с целью уточнения состояния [35,90]."}, "d-nsg": {"s": "ok", "sec": "2.4", "page": 21, "q": "Рекомендуется проведение нейросонографии пациентам 1-го года жизни при появлении или утяжелении неврологической симптоматики на фоне коклюша для уточнения состояния церебральных структур [35,91]."}, "d-bronch": {"s": "ok", "sec": "2.4", "page": 21, "q": "Рекомендуется проведение бронхоскопии пациентам с обширными или длительно не расправляющимися ателектазами (в течение двух и более недель) с целью уточнения бронхиальной проходимости [1, 35]."}, "d-spo2": {"s": "ok", "sec": "2.4", "page": 21, "q": "Пациентам с тяжелой степенью тяжести коклюша рекомендуется проведение пульсоксиметрии для контроля сатурации [36,92]. Уровень убедительности рекомендаций С (уровень достоверности доказательств - 5). Комментарии: Целесообразно проводить пациентам с тяжелой степенью тяжести коклюша при наличии осложнений (задержки дыхания, судороги) и/или с клиническими проявлениями пневмонии или бронхообструктивного синдрома (наличие одыщки, тахипноэ, цианоза) для уточнения показаний к искусственной вентиляции легких (ИВЛ)."}, "d-ophth": {"s": "ok", "sec": "2.5", "page": 21, "q": "Рекомендуется осмотр врача офтальмолога (прием, (осмотр, консультация) врачаофтальмолога первичный)) пациентам с коклюшем при развитии субконъюнктивальных кровоизлияний с целью определения тактики их лечения"}, "d-neuro": {"s": "ok", "sec": "2.5", "page": 22, "q": "Рекомендуется консультация невролога (прием, (осмотр, консультация) врача-невролога первичный) пациентам с тяжелыми формами коклюша при развитии неврологической симптоматики или при наличии коморбидной неврологической патологии с целью коррекции проводимой терапии"}, "t-goal": {"s": "ok", "sec": "3", "page": 22, "q": "Цели лечения: • эрадикация возбудителя; • купирование приступов судорожного кашля; • предупреждение развития осложнений или их лечение, в том числе угрожающих жизни (апноэ, коклюшная энцефалопатия, включающая гипоксический отек мозга и внутричерепные кровоизлияния)."}, "t-abx": {"s": "ok", "sec": "3.1", "page": 22, "q": "Рекомендуется всем пациентам с коклюшем назначать антибактериальные препараты системного действия с целью эрадикации возбудителя из группы макролидов или пенициллинов широкого спектра действия", "note": "Первая очередь — макролиды, при непереносимости — пенициллины широкого спектра или цефалоспорины 3 поколения (комментарий)."}, "t-abx-dose": {"s": "ok", "sec": "3.1", "page": 23, "q": "Рекомендованная доза азитромицина** (у детей старше 6 мес) – 10 мг/кг/сут в один прием в течение 5 дней [79-81]. - Эритромицин (J01FA01) рекомендован внутрь в разовой дозе 10-15 мг/кг каждые 8 часов, не более 2 грамм в сутки, в течение 14 дней [79-81]. - #Кларитромицин** (J01FA09) (перорально) у детей старше 1 месяца из расчета 7,5 мг/кг два раза в день, не более 1 г в сутки, в течение 7-14 дней [79-81]. - #Пиперациллин-тазобактам (J01CR05)– рекомендовано внутривенное введение детям с коклюшем тяжелой степени тяжести, в том числе, младше 2 месяцев жизни. Рекомендованная разовая доза 40-50 мг/кг каждые 8 часов в течение 1-2 недель. Терапия эффективна при сочетанной инфекции с Streptococcus pneumoniae, Haemophilus influenzae, Moraxella catarrhalis [79-81]. - #Цефоперазон-сульбактам** (J01DD62) в дозе 50-60 мг/кг внутривенно каждые 12 часов в течение 1-2 недель. Рекомендовано введение детям с коклюшем тяжелой степени тяжести. - Возможно назначение цефотаксима**, цефтриаксона**, ампициллина** и амоксициллина** (дозировки согласно инструкции) [79-81]."}, "t-abx-when": {"s": "ok", "sec": "3.1", "page": 23, "q": "Антибактериальная терапия рекомендована для лечения коклюша с целью эрадикации возбудителя у пациентов первого года жизни, обратившихся за медицинской помощью в течение 6 недель от начала заболевания, пациентам других возрастных категорий, обратившихся в течение 3 недель от начала заболевания. Антибактериальная терапия уменьшает колонизацию B.pertussis и контагиозность коклюша, что особенно актуально в ранние сроки заболевания, однако не влияет на выраженность и длительность симптомов заболевания (в частности, приступообразного судорожного кашля). Назначение антибактериальной терапии вне зависимости от сроков заболевания рекомендовано пациентам с бронхолегочными осложнениями, вызванными вторичной бактериальной флорой, и наличием сопутствующих хронических заболеваний легких."}, "t-azi-susp": {"s": "ok", "sec": "3.1", "page": 22, "q": "Азитромицин** (J01FA10) в суспензии (100 мг/5 мл) применяют внутрь 1 раз в сутки в разовой дозе у детей (старше 6 мес) с массой тела от 5.0 кг – 2,5 мл суспензии (50 мг азитромицина**), 6 кг – 3.0 мл (60 мг азитромицина**) 7,0 кг – 3,5 мл (70 мг азитромицина**, 8 кг – 4,0 мл (80 мг азитромицина**), 9 0 кг – 4,5 мл (90 мг азитромицина**), 10 кг – 5 мл 22  (100 мг азитромицина**). - Азитромицин** (200 мг/5) мл в суспензии применяют внутрь 1 раз в сутки в разовой дозе у детей с массой тела 10-14 кг – 2,5 мл суспензии (100 мг азитромицина**), 15-24 кг – 5,0 мл (200 мг азитромицина**), 25-34 кг – 7,5 мл (300 мг азитромицина**), 35-44 кг – 10 мл (400 мг азитромицина**), 45 и более кг – 12,5 мл (500 мг азитромицина**), что соответствует дозе взрослых."}, "t-abx-any": {"s": "ok", "sec": "3.1", "page": 23, "q": "Назначение антибактериальной терапии вне зависимости от сроков заболевания рекомендовано пациентам с бронхолегочными осложнениями, вызванными вторичной бактериальной флорой, и наличием сопутствующих хронических заболеваний легких."}, "t-carrier": {"s": "ok", "sec": "3.1", "page": 24, "q": "Рекомендовано в очагах коклюша бессимптомным носителям проводить антибактериальную терапию (предпочтительно макролидами) только в случаях тесного контакта с детьми групп риска тяжелого течения коклюша и по эпидемическим показаниям для профилактики инфицирования детей из групп риска"}, "t-risk": {"s": "ok", "sec": "3.1", "page": 24, "q": "К группам риска развития коклюша тяжелой степени тяжести относятся [53, 79]: 1. Младенцы моложе 3-х месяцев, 2. Не привитые младенцы или не получившие полный первичный вакцинальный комплекс; 3. Недоношенные дети или новорожденные с низкой массой тела при рождении или оценкой по шкале Апгар менее 8; 4. Тяжелые врожденные заболевания сердца; 5. Лейкоцитоз более 20*109/л за счет лимфоцитоза более 10*109/л6. 6. Апноэ и цианоз в дебюте заболевания; 7. Ко-инфекция или сопутствующая пневмония."}, "t-antitus": {"s": "ok", "sec": "3.1", "page": 24, "q": "Рекомендуется применение противокашлевых препаратов, кроме комбинаций с отхаркивающими средствами R05D (противокашлевых лекарственных средств центрального действия) пациентам со спазматическим кашлем для облегчения приступов кашля [37, 39, 43-45]. Уровень убедительности рекомендаций С (уровень достоверности доказательств - 5). Комментарии: Противокашлевые препараты центрального действия (противокашлевые препараты, кроме комбинаций с отхаркивающими средствами) на основе бутамирата (R05DB13) назначаются в каплях с 2-х месяцев возрастных дозировках, в каплях, сиропе, таблетках с модифицированным высвобождение) согласно инструкции."}, "t-muco": {"s": "ok", "sec": "3.1", "page": 24, "q": "Пациентам при наличии обильной, вязкой трудноотделяемой мокроты с целью облегчения ее отхождения рекомендуется применение лекарственных средств с муколитическим действием (муколитические препараты) (амброксол**) (R05CB06) [37, 39, 44]. Уровень убедительности рекомендаций С (уровень достоверности доказательств - 5). Комментарии: Лекарственные средства с муколитическим эффектом (муколитические препараты) будут способствовать лучшему отхождению мокроты. Назначаются в соответствии с инструкцией к применению. Не рекомендуется одновременное применение противокашлевых и муколитических средств (противокашлевые препараты в комбинации с муколитиками) в связи с подавлением кашлевого рефлекса и нарушением отхождения мокроты [37, 39, 44]."}, "t-o2": {"s": "ok", "sec": "3.1", "page": 24, "q": "Рекомендуется оксигенотерапия при среднетяжелых, тяжелых и осложненных формах коклюша при выявлении дыхательных расстройств, коклюшной энцефалопатии или 24  поражения нижних дыхательных путей для профилактики и коррекции гипоксии [36 - 39, 50, 54, 55, 79]. Уровень убедительности рекомендаций C (уровень достоверности доказательств -4). Комментарии: Оксигенотерапия проводится в кислородной палатке или с помощью маски кислородно-воздушной смесью, в которой чистый кислород составляет не более 40%. Гипоксия часто ассоциирована с приступами пароксизмального кашля и приводит к брадикардии. Показанием к назначению кислорода являются следующие признаки: бледность, цианоз, брадикардия, снижение сатурации менее 93%, в том числе, во время кашлевого пароксизма."}, "t-o2-apnea": {"s": "ok", "sec": "3.1", "page": 25, "q": "В случае остановки дыхания у пациента следует как можно быстрее добиться восстановления нормальных дыхательных движений путем ритмичного надавливания руками на грудную клетку и применения искусственного дыхания с использованием ручных респираторов. При повторных задержках дыхания или развитии остановки дыхания (более 30 сек) ребенка следует перевести в отделение реанимации и интенсивной терапии."}, "t-icu": {"s": "ok", "sec": "3.1", "page": 25, "q": "Рекомендована консультация врача-анестезиолога-реаниматолога (осмотр (консультация) врачом-анестезиологом-реаниматологом первичный) с целью перевода ребенка в отделение реанимации и интенсивной терапии при наличии или появлении у больного признаков тяжелого коклюша и его специфических осложнений, угрожающих жизни [54, 55] Уровень убедительности рекомендаций С (уровень достоверности доказательств - 4). Комментарии: Признаками утяжеления состояния и развития отека мозга являются: судороги, нарушение ритма дыхания (апноэ), выбухание и пульсация большого родничка, любая степень угнетения сознания, изменения ритма мочеиспусканий и нарастание отечного синдрома, поражение нижних дыхательных путей, одышка, цианоз лица при кашле)"}, "t-gcs": {"s": "ok", "sec": "3.1", "page": 25, "q": "При коклюшной энцефалопатии, обусловленной развитием гипоксического отека головного мозга (судороги, угнетение сознания), в случаях нарушениях ритма дыхания, при наличии разлитого цианоза лица при приступах кашля у детей первых месяцев жизни: #гидрокортизон** (в дозах 5–7 мг на 1 кг массы тела ребенка в течение 3 дней), преднизолон** или дексаметазон**. Длительность курса 2-3-5 дней, не более 7-9 дней [88]."}, "t-diaz": {"s": "ok", "sec": "3.1", "page": 26, "q": "Рекомендуется пациентам с коклюшем при развитии судорог на фоне коклюшной энцефалопатии с целью их купирования назначение препаратов бензодиазепинов (производных бензодиазепина). #Диазепам** вводится внутривенно или внутримышечно (в 2 мл раствора содержится 10 мг препарата) в разовой дозе 0,25 мг/кг; возможно применение 2 раза в сутки. Суточная доза #диазепама** не более 5 мг для детей до 5 лет; 20 мг — для детей 6—12 лет и 40 мг — для детей старше 12 лет при развитии судорожного синдрома на фоне коклюшной энцефалопатии в качестве противосудорожного, миорелаксирующего, седативного средства. #Диазепам** назначают внутримышечно или внутривенно согласно инструкции [47]."}, "t-diaz-c": {"s": "ok", "sec": "3.1", "page": 26, "q": "назначают и другие противосудорожные препараты (противоэпилептические препараты) по назначению врача-анестезиолога-реаниматолога или врача-невролога [2, 38, 40, 47- 49]."}, "t-pheno": {"s": "ok", "sec": "3.1", "page": 26, "q": "Рекомендуется при тяжелой степени тяжести коклюша назначение детям раннего возраста фенобарбитала ** (для детей с 3 лет) для уменьшения гипоксии головного мозга [1, 37, 38]."}, "t-suction": {"s": "ok", "sec": "3.3", "page": 26, "q": "При затруднении откашливания секрета пациентам с коклюшем рекомендовано отсасывание слизи из верхних дыхательных путей с применением электроотсоса с целью санации дыхательных путей [37, 38,93]. Уровень убедительности рекомендаций С (уровень достоверности доказательств - 5). Комментарии: Рекомендуется плановое (2-3 раза в день) или по показаниям удаление из верхних дыхательных путей при их обильном выделении и отсутствии самостоятельной эвакуации, что преимущественно отмечается у детей первого года жизни."}, "t-orvi": {"s": "ok", "sec": "3.3", "page": 26, "q": "Рекомендуется пациентам с коклюшем, имеющим сочетанную острую респираторную вирусную инфекцию, терапия противовирусными препаратами системного действия или иммуностимуляторы (Интерферона альфа 2b **, Меглюмина акридонацетат (у детей с 4 лет), Анаферон детский (Антитела к гамма-интерферону афинно очищенные (у детей старше 1 мес), 26  Эргоферон (Антитела к гамма-интерферону афинноочищенные, антитела к гистамину афинно очищенные, антитела к CD4 афинно очищенные) у детей старше 6 мес) с целью лечения микстинфекции"}, "t-rehab": {"s": "ok", "sec": "4", "page": 27, "q": "Специальных программ реабилитации при заболевании коклюшем не разработано. • Реконвалесцентам тяжелого коклюша негладкого течения (коклюшная энцефалопатия, пневмония), а также при наличии коморбидных состояний (бронхиальная астма, кардиомиопатия, миокардит в анамнезе, пороки сердца или бронхолегочной системы, иммунодефицитные состояния различного генеза) рекомендованы реабилитационные мероприятия по назначению профильных врачей специалистов с учетом характера осложнений или фоновых заболеваний, а также санаторно-курортное лечение с целью коррекции последствий перенесенного заболевания."}, "h-where": {"s": "ok", "sec": "6", "page": 35, "q": "Лечение пациентов с диагнозом «коклюш» легкой и средней степени тяжести при отсутствии факторов риска осуществляется в амбулаторных условиях под наблюдением врача педиатра (врача общей практики, врача инфекциониста). Пациенты с тяжелой степенью тяжести или среднетяжелой при наличии факторов риска, а также по эпидемиологическим показаниям - в условиях стационара (в инфекционном отделении/ инфекционных койках), имеющих отделения реанимации и интенсивной терапии, при развитии угрожающих жизни осложнений - в условиях отделения реанимации и интенсивной терапии (ОРИТ). В стационаре пациенты с подозрением на коклюш и пациенты с подтвержденным диагнозом должны быть размещены в отдельных боксах/палатах для предотвращения внутрибольничного инфицирования."}, "h-icu": {"s": "ok", "sec": "6", "page": 36, "q": "Показания для перевода в отделение реанимации и интенсивной терапии [36,69,66]. • брадикардия или кашлевой пароксизм, который вызывает десатурацию до SpO2 <90%; • цианоз, вялость, выраженная бледность; • любое апноэ > 15 секунд у младенца или > 10 секунд у новорожденного; • апноэ любой продолжительности, если оно вызывает десатурацию (цианоз лица, акроцианоз); • любая другая прогрессирующая дыхательная недостаточность, приводящая к тяжелой респираторной недостаточности или SpO2 <90%; • угнетение сознания; • судороги • подозрение на отек головного мозга."}, "h-out": {"s": "ok", "sec": "6", "page": 36, "q": "Критерии выписки из стационара: удовлетворительное состояние пациента"}, "h-recov": {"s": "ok", "sec": "7", "page": 39, "q": "Критерии выздоровления: • отсутствие тяжелых приступов кашля с репризами (пароксизмов); • отсутствие или уменьшение количества приступов кашля; 39  • нормализация гемограммы (возможно длительное сохранение лимфоцитоза); • при развитии пневмонии - нормализация клинической, гематологической и рентгенологической картины."}, "p-iso": {"s": "ok", "sec": "5", "page": 28, "q": "Информация о каждом выявленном случае заболевания передается из ЛПУ в течение 2 часов по телефону и в течение 12 часов направляется экстренное извещение в территориальный орган федерального органа исполнительной власти, уполномоченного на осуществление федерального государственного санитарно-эпидемиологического надзора, по месту выявления пациента (независимо от места его проживания). Активная иммунизация в очаге не проводится. В очагах рекомендовано проведение неспецифической постконтактной профилактики и наблюдение за контактными. Пациенты детского возраста с коклюшем подлежат обязательной изоляции на 25 суток от начала заболевания. На контактных детей в возрасте до 7 лет накладывается карантин сроком на 14 суток от момента изоляции больного (контактными считаются как непривитые, так и привитые против коклюша дети). В это время запрещается прием новых детей, не болевших коклюшем, и перевод из одной группы в другую. Назначают ограничительные мероприятия для данных групп (смещение расписания занятий и прогулок, запрещение посещений общих мероприятий). С целью раннего выявления кашляющих (больных) в очаге коклюша проводят ежедневное медицинское наблюдение за контактными детьми и взрослыми. Дети старше 7 лет разобщению не подлежат."}, "p-after": {"s": "ok", "sec": "5", "page": 28, "q": "Порядок снятия ограничений: выписка в детский коллектив реконвалесцентов коклюша осуществляется при клиническом выздоровлении на основании осмотра врачом. При отсутствии осложнений в реабилитации и диетических ограничениях не нуждаются. Освобождаются от занятий физической культурой после выздоровления сроком на 2 недели. Медицинский отвод от прививок на 1 месяц."}, "p-pep": {"s": "ok", "sec": "5", "page": 28, "q": "Рекомендуется всем контактным детям (в том числе новорожденным) и взрослым, после изоляции больного, проведение неспецифической постконтактной профилактики с целью локализации и ликвидации очага коклюша", "note": "Препараты выбора — «Антибиотиками выбора для проведения экстренной постконтактной профилактики являются препараты группы макролидов»."}, "p-pep-c": {"s": "ok", "sec": "5", "page": 28, "q": "Постконтактная неспецифическая профилактика коклюша проводится детям и взрослым, независимо от возраста и вакцинального статуса в случаях, если имелся тесный контакт с больным манифестной формой коклюша в закрытом помещении в течение 1 часа и более, или имелся контакт с респираторными секретами больного манифестной формой коклюша."}, "p-ig": {"s": "ok", "sec": "5", "page": 29, "q": "Рекомендуется детям первого года жизни и непривитым детям в возрасте до 2 лет, имеющим медикаментозную аллергию к макролидным антибиотикам, ввести иммуноглобулин человека нормальный** двукратно с интервалом 24 часа в разовой дозе 3,0 мл в возможно более ранние сроки после контакта с больным"}, "p-vacc": {"s": "ok", "sec": "5", "page": 29, "q": "В соответствии с национальным календарем прививок, профилактику коклюша, дифтерии, столбняка проводят в 3 - 4,5 - 6 - 18 мес. При нарушении сроков иммунизации необходимо стремиться к выполнению полного вакцинального комплекса, т.е. 3-х кратной вакцинации с минимальным интервалом 1-1,5 мес. и ревакцинацией через 12 мес. после третьего введения. При увеличении интервалов между введениями вакцины, вне зависимости от их длительности, дополнительных вакцинаций не требуется."}, "p-vacc-c": {"s": "ok", "sec": "5", "page": 29, "q": "Перенесённое заболевание (коклюш) не приводит к образованию длительной защиты и не является противопоказанием для дальнейшего введения вакцин, содержащих коклюшный компонент.", "note": "Активная иммунизация в очаге не проводится; частично вакцинированным — по календарю (там же)."}, "p-preg": {"s": "ok", "sec": "5", "page": 31, "q": "для профилактики коклюша у детей с рождения до момента начала вакцинации может быть рекомендована однократная вакцинация беременных во II или III триместрах, но не позднее 15 дней до даты родов, вакциной с уменьшенным содержанием коклюша, дифтерии, столбняка АакдС"}, "p-revac": {"s": "ok", "sec": "5", "page": 30, "q": "Оптимальной стратегией по снижению заболеваемости и смертности, предотвращению экономических потерь от коклюшной инфекции является [48, 52, 66]: - максимальный своевременный охват профилактическими прививками детей первых двух лет жизни, в сроки, декретированные национальным календарём профилактических прививок (в 3-4,5-6-18 мес.,) догоняющая иммунизация для детей, не привитых своевременно; - поэтапное внедрение в практическое здравоохранение возрастных ревакцинации 30  против коклюша детей в 6-7 лет, 14 лет, подростков и взрослых с 18 лет - каждые 10 лет с момента последней ревакцинации. При внедрении возрастных ревакцинаций первоочередными группами риска, нуждающимися в ревакцинации против коклюша, являются: - пациенты (дети и взрослые) с хронической бронхолёгочной патологией, бронхиальной астмой, - с иммунодефицитными состояниями, в том числе ВИЧ-инфицированные, с онкологическими заболеваниями; - дети, ранее первично привитые бесклеточными вакцинами; - дети из многодетных семей; - дети, проживающие в закрытых учреждениях; - взрослые - сотрудники медицинских, образовательных, интернатных учреждений, учреждений социального обеспечения; - взрослые в семьях, где есть новорожденные и не привитые дети до 1 года (кормление грудью не является противопоказанием к вакцинации женщины); - женщины, планирующие беременность."}, "p-vaccines": {"s": "ok", "sec": "5", "page": 29, "q": "Вакцины для профилактики коклюша, дифтерии, столбняка, зарегистрированные в РФ:  Вакцина для профилактики дифтерии, коклюша и столбняка** (АКДС)- для детей с 3-х мес. до 3-х лет 11 мес. 29 дней; 29  Вакцина для профилактики коклюша, дифтерии, столбняка и гепатита В адсорбированная жидкая (АКДС-Геп В) **, - для детей с 3-х мес. до 3-х лет 11 мес. 29 дней;  Вакцина для профилактики дифтерии, коклюша (бесклеточная) и столбняка** (АаКДС) - для детей с 2 мес до 7 лет;  Вакцина для профилактики дифтерии, столбняка, коклюша ацеллюлярная, полиомиелита инактивированная и инфекций, вызываемых Haemophilus ifluenzae тип b, конъюгированная** (АаКДС-ИПВ//ХИБ) - для детей с 2-х мес. При нарушении сроков вакцинации возможно её использование до возраста 6 лет (затем переход на вакцины с уменьшенным содержанием антигенов); Вакцинация против Hib-инфекции проводится до возраста 5 лет.  Вакцина для профилактики дифтерии, столбняка, коклюша (бесклеточная), гепатита В рекомбинантная, полиомиелита (инактивированная) и инфекций, вызываемых Haemophilus influenzae тип b, конъюгированная, адсорбированная ** (АаКДС-ИПВ-ВГВ//ХИБ) - для детей с 2-х мес. до 2-х лет", "note": "АакдС — «для детей с 4-х лет и взрослых, разрешено применение у беременных женщин»."}, "p-disp-1": {"s": "ok", "sec": "5, табл. 1", "page": 32, "q": "Рекомендуемые сроки наблюдения за реконвалесцентами коклюша [4, 58,69]. Таблица 1 Наблюдение Длительность Показания и периодичность осмотров специалистов наблюдения врачей-специалистов 2 3 4 32  1 врачпульмонолог, врач-педиатр 6 месяцев 2 врач-невролог, врач-педиатр 1 год Реконвалесценты среднетяжелых и тяжелых форм коклюша, осложненного пневмонией, ателектазом, дыхательными расстройствами через 2 и 6 месяцев после выписки"}, "p-disp-2": {"s": "ok", "sec": "5, табл. 1", "page": 33, "q": "Реконвалесценты тяжелых форм коклюша, осложненного коклюшной энцефалопатией с судорожным синдромом, внутричерепной гипертензией, внутричерепными кровоизлияниями через 2, 6 и 12 месяцев после выписки"}, "x-out": {"s": "ok", "sec": "7, табл. 4", "page": 39, "q": "При остром заболевании практически полное 3 частичным нарушением исчезновение всех симптомов, но у реконвалесцентов физиологического тяжелых форм коклюша, осложненных коклюшной процесса, или потери энцефалопатией, возможны задержки психомоторного и функции речевого развития. После внутримозговых кровоизлияний возможно снижение слуха и зрения, развитие парезов и параличей"}}, "terms": {"a:АКДС": {"t": "АКДС", "q": "вакцина для профилактики дифтерии, коклюша и столбняка", "sec": "Список сокращений", "page": 4, "re": "(?<![\\w-])АКДС(?![\\w-])"}, "a:АКДС- ВГВ": {"t": "АКДС- ВГВ", "q": "вакцина для профилактики вирусного гепатита В и Вакцина для профилактики дифтерии, коклюша и столбняка", "sec": "Список сокращений", "page": 4, "re": "(?<![\\w-])АКДС\\-\\ ВГВ(?![\\w-])"}, "a:АаКДС": {"t": "АаКДС", "q": "вакцина для профилактики дифтерии, коклюша (бесклеточная) и столбняка", "sec": "Список сокращений", "page": 4, "re": "(?<![\\w-])АаКДС(?![\\w-])"}, "a:АакдС": {"t": "АакдС", "q": "вакцина для профилактики дифтерии (с уменьшенным содержанием антигена), коклюша (с уменьшенным содержанием антигена, бесклеточная) и столбняка, адсорбированная", "sec": "Список сокращений", "page": 4, "re": "(?<![\\w-])АакдС(?![\\w-])"}, "a:АаКДС-ВГВ//ХИБ": {"t": "АаКДС-ВГВ//ХИБ", "q": "вакцина для профилактики дифтерии, столбняка, коклюша (бесклеточная), гепатита В и инфекции, вызываемой Haemophilus influenzae тип b", "sec": "Список сокращений", "page": 4, "re": "(?<![\\w-])АаКДС\\-ВГВ//ХИБ(?![\\w-])"}, "a:АаКДС-ИПВ//ХИБ": {"t": "АаКДС-ИПВ//ХИБ", "q": "вакцина для профилактики дифтерии, столбняка, коклюша, полиомиелита и инфекций, вызываемых Haemophilus influenzae тип b", "sec": "Список сокращений", "page": 4, "re": "(?<![\\w-])АаКДС\\-ИПВ//ХИБ(?![\\w-])"}, "a:АаКДС-ИПВ-ВГВ//ХИБ": {"t": "АаКДС-ИПВ-ВГВ//ХИБ", "q": "вакцина для профилактики дифтерии, столбняка, коклюша (бесклеточная), гепатита В, полиомиелита (инактивированная) и инфекций, вызываемых Haemophilus influenzae тип b", "sec": "Список сокращений", "page": 4, "re": "(?<![\\w-])АаКДС\\-ИПВ\\-ВГВ//ХИБ(?![\\w-])"}, "a:АДС-М": {"t": "АДС-М", "q": "анатоксин дифтерийно-столбнячный с уменьшенным содержанием антигенов", "sec": "Список сокращений", "page": 4, "re": "(?<![\\w-])АДС\\-М(?![\\w-])"}, "a:ДВС": {"t": "ДВС", "q": "диссеминированное внутрисосудистое свертывание", "sec": "Список сокращений", "page": 4, "re": "(?<![\\w-])ДВС(?![\\w-])"}, "a:ГКГ": {"t": "ГКГ", "q": "глюкокортикоидные гормоны", "sec": "Список сокращений", "page": 4, "re": "(?<![\\w-])ГКГ(?![\\w-])"}, "a:ИТШ": {"t": "ИТШ", "q": "инфекционно-токсический шок", "sec": "Список сокращений", "page": 4, "re": "(?<![\\w-])ИТШ(?![\\w-])"}, "a:ИФА": {"t": "ИФА", "q": "иммуноферментный анализ", "sec": "Список сокращений", "page": 4, "re": "(?<![\\w-])ИФА(?![\\w-])"}, "a:ОАМ": {"t": "ОАМ", "q": "общий (клинический) анализ мочи", "sec": "Список сокращений", "page": 4, "re": "(?<![\\w-])ОАМ(?![\\w-])"}, "a:РА": {"t": "РА", "q": "реакция агглютинации", "sec": "Список сокращений", "page": 4, "re": "(?<![\\w-])РА(?![\\w-])"}, "a:РНГА": {"t": "РНГА", "q": "реакция непрямой гемагглютинации", "sec": "Список сокращений", "page": 4, "re": "(?<![\\w-])РНГА(?![\\w-])"}, "a:СКД": {"t": "СКД", "q": "средняя курсовая доза", "sec": "Список сокращений", "page": 4, "re": "(?<![\\w-])СКД(?![\\w-])"}, "a:ССД": {"t": "ССД", "q": "средняя суточная доза", "sec": "Список сокращений", "page": 4, "re": "(?<![\\w-])ССД(?![\\w-])"}, "a:ЦМВИ": {"t": "ЦМВИ", "q": "цитомегаловирусная инфекция", "sec": "Список сокращений", "page": 5, "re": "(?<![\\w-])ЦМВИ(?![\\w-])"}, "a:ЭхоКГ": {"t": "ЭхоКГ", "q": "эхокардиографическое исследование", "sec": "Список сокращений", "page": 5, "re": "(?<![\\w-])ЭхоКГ(?![\\w-])"}, "a:ЭЭГ": {"t": "ЭЭГ", "q": "электроэнцефалография", "sec": "Список сокращений", "page": 5, "re": "(?<![\\w-])ЭЭГ(?![\\w-])"}, "a:Ig M, G": {"t": "Ig M, G", "q": "иммуноглобулины М,", "sec": "Список сокращений", "page": 5, "re": "(?<![\\w-])Ig\\ M,\\ G(?![\\w-])"}, "d:Репризы": {"t": "Репризы", "q": "звучные судорожные вдохи, возникающие при прохождении воздуха через суженную вследствие ларингоспазма голосовую щель", "sec": "Термины и определения", "page": 7, "re": "(?<![\\w-])(?i:Р)епри[а-яё]{0,4}(?![\\w-])"}, "d:Ларингоспазм": {"t": "Ларингоспазм", "q": "внезапное непроизвольное сокращение мышц гортани, приводящее к частичному или полному закрытию голосовой щели и временной обструкции дыхательных путей", "sec": "Термины и определения", "page": 5, "re": "(?<![\\w-])(?i:Л)арингоспа[а-яё]{0,4}(?![\\w-])", "cv": "305_2", "kr": "Парезы и параличи гортани", "slug": "parezy-i-paralichi-gortani"}, "d:Лёгочная гипертензия": {"t": "Лёгочная гипертензия", "q": "клинический синдром, характеризующийся повышением среднего давления в лёгочной артерии ≥ 25 мм рт. ст. в покое, измеренного при чрезвенозной катетеризации сердца.", "sec": "Термины и определения", "page": 5, "re": "(?<![\\w-])(?i:Л)ёгочн[а-яё]{0,4}\\s+гипертенз[а-яё]{0,4}(?![\\w-])", "cv": "736_2", "kr": "Саркоидоз", "slug": "sarkoidoz"}, "d:Апноэ": {"t": "Апноэ", "q": "остановка дыхания во время сна.", "sec": "Термины и определения", "page": 5, "re": "(?<![\\w-])(?i:А)пноэ(?:ь|и|ью|ей|я|ю|ем|ями|ях|ям|а|ы|е|у|ой|ою|ам|ами|ах|ом|ов|о)?(?![\\w-])", "cv": "913_1", "kr": "Деформация перегородки носа", "slug": "deformatsiya-peregorodki-nosa"}, "d:Bordetella pertussis": {"t": "Bordetella pertussis", "q": "Возбудитель коклюша: грамотрицательная гемолитическая палочка, неподвижная, не образующая капсул и спор, неустойчивая во внешней среде.", "book": "КР «Коклюш у детей», раздел «Этиология и патогенез», с. 8", "re": "Bordetella\\s+pertussis"}, "d:Гипоксия": {"t": "Гипоксия", "q": "Общее патологическое состояние организма, возникающее при недостаточном снабжении тканей кислородом или нарушении его утилизации.", "book": "Бабияк В. И., Накатис Я. А., Говорун М. И. «Оториноларингология. Руководство», т. 2 (СПб.: Питер, 2009), с. 93", "re": "(?<![\\w-])(?i:Г)ипокс[а-яё]{0,4}(?![\\w-])"}, "d:Аденовирус": {"t": "Аденовирус", "q": "ДНК-содержащий вирус семейства Adenoviridae, рода Mastadenovirus.", "book": "КР «Острая респираторная вирусная инфекция (ОРВИ)», раздел «Этиология и патогенез», с. 8", "re": "(?<![\\w-])(?i:А)деновир[а-яё]{0,4}(?![\\w-])"}, "d:Парагрипп": {"t": "Парагрипп", "q": "Острая респираторная вирусная инфекция, вызываемая вирусом парагриппа человека (HPIV).", "book": "КР «Острая респираторная вирусная инфекция (ОРВИ)», раздел «Этиология и патогенез», с. 9", "re": "(?<![\\w-])(?i:П)арагри[а-яё]{0,4}(?![\\w-])"}, "d:Бронхоскопия": {"t": "Бронхоскопия", "q": "Эндоскопическое исследование бронхов (в современной практике чаще видеотрахеобронхоскопия): осматривают трахею и бронхи, до сегментарных бронхов 4–5 порядка, и берут биопсии из бронхов разного уровня и из лёгочной ткани.", "book": "КР «Туберкулез у взрослых», раздел «Диагностика», с. 39", "re": "(?<![\\w-])(?i:Б)ронхоскоп[а-яё]{0,4}(?![\\w-])"}, "d:Иммуноглобулины": {"t": "Иммуноглобулины", "q": "Антитела: особые белки, которые вырабатываются организмом в ответ на контакт с чужеродными агентами (инфекциями). IgG составляет основную часть антител плазмы и играет главную роль в защите от инфекций; IgA обеспечивает местный иммунитет (кровь, слюна, слёзы); IgM действует при первой встрече с инфекцией; IgE участвует в аллергических реакциях и защите от паразитов.", "book": "КР «Первичные иммунодефициты с преимущественной недостаточностью синтеза антител», раздел «Информация для пациента» (приложение В), с. 65", "re": "(?<![\\w-])(?i:И)ммуноглобули[а-яё]{0,4}(?![\\w-])"}, "d:Цитомегаловирусная инфекция": {"t": "Цитомегаловирусная инфекция", "q": "Распространённая вирусная инфекция, вызываемая цитомегаловирусом (Human Cytomegalovirus); проявления различны, от бессимптомного течения до тяжёлых генерализованных форм с поражением внутренних органов и центральной нервной системы.", "book": "КР «Врожденная цитомегаловирусная инфекция», раздел «Термины и определения», с. 6", "re": "(?<![\\w-])(?i:Ц)итомегаловирусн[а-яё]{0,4}\\s+инфекц[а-яё]{0,4}(?![\\w-])"}, "d:Носоглотка": {"t": "Носоглотка", "q": "Верхний отдел глотки; через хоаны сообщается с полостью носа. В боковой стенке находятся глоточные устья слуховых труб, свод по форме напоминает трапецию.", "book": "Бабияк В. И., Накатис Я. А., Говорун М. И. «Оториноларингология. Руководство», т. 1 (СПб.: Питер, 2009), с. 418, 46", "re": "(?<![\\w-])(?i:Н)осоглот[а-яё]{0,4}(?![\\w-])"}, "d:Голосовая щель": {"t": "Голосовая щель", "q": "Самая узкая часть гортани, образованная сверху складками преддверия, снизу голосовыми складками. Пространство над ней называется надскладочным, под ней подскладочным. Ширина голосовой щели — наибольшее расстояние между голосовыми складками при вдохе; в норме у взрослого 15–19 мм.", "book": "Бабияк В. И., Накатис Я. А., Говорун М. И. «Оториноларингология. Руководство», т. 2 (СПб.: Питер, 2009), с. 20; Пальчун В. Т., Лучихин Л. А., Магомедов М. М. «Руководство по практической оториноларингологии» (М.: МИА, 2010), с. 52", "re": "(?<![\\w-])(?i:Г)олосов[а-яё]{0,4}\\s+щел(?:ь|и|ью|ей|я|ю|ем|ями|ях|ям|а|ы|е|у|ой|ою|ам|ами|ах|ом|ов|о)?(?![\\w-])"}, "d:Дифтерия": {"t": "Дифтерия", "q": "Острое инфекционное заболевание (от греч. diphthera — кожа, плёнка) с интоксикацией и воспалением в зеве и глотке, реже в гортани, трахее, носу и других органах, с образованием налётов, сливающихся с некротизированной тканью поражённых слизистых оболочек.", "book": "Бабияк В. И., Накатис Я. А., Говорун М. И. «Оториноларингология. Руководство», т. 1 (СПб.: Питер, 2009), с. 508", "re": "(?<![\\w-])(?:(?i:д)ифтери\\w+)(?![\\w-])"}, "d:Интоксикация": {"t": "Интоксикация", "q": "Патологическое состояние, вызванное действием на организм токсических веществ, попавших извне (экзогенная) или образовавшихся в самом организме (эндогенная). Обычно проявляется повышением температуры тела, слабостью, головной болью, бессонницей, тошнотой; в тяжёлых случаях — рвотой, судорогами, нарушением сознания.", "book": "Бабияк В. И., Накатис Я. А., Говорун М. И. «Оториноларингология. Руководство», т. 1 (СПб.: Питер, 2009), с. 699", "re": "(?<![\\w-])(?i:И)нтоксикац[а-яё]{0,4}(?![\\w-])"}, "d:Отёчный ларингит": {"t": "Отёчный ларингит", "q": "Форма ларингита: воспалительный отёк гортани с гиперемией слизистой оболочки, лейкоцитарной и лимфоцитарной инфильтрацией периваскулярных пространств и пропитыванием подслизистого слоя серозным транссудатом. У взрослых чаще возникает в преддверии гортани, у детей в подскладочном пространстве.", "book": "Бабияк В. И., Накатис Я. А., Говорун М. И. «Оториноларингология. Руководство», т. 2 (СПб.: Питер, 2009), с. 77, 78", "re": "(?<![\\w-])(?:(?i:о)тёчн(?:ый|ая форма)(?!\\s+паратонзиллит))(?![\\w-])"}, "d:Ротоглотка": {"t": "Ротоглотка", "q": "Средний отдел глотки. Спереди он граничит с зевом, который сверху ограничен мягким нёбом, снизу корнем языка, с боков передними и задними нёбными дужками.", "book": "Бабияк В. И., Накатис Я. А., Говорун М. И. «Оториноларингология. Руководство», т. 1 (СПб.: Питер, 2009), с. 418", "re": "(?<![\\w-])(?i:Р)отоглот[а-яё]{0,4}(?![\\w-])"}, "d:Носогубная киста": {"t": "Носогубная киста", "q": "Носоальвеолярная киста: возникает из того же эпителия, что и шаровидно-верхнечелюстная; расположена на передней поверхности верхней челюсти в проекции верхушки корня бокового резца и клыка.", "book": "КР «Кисты челюстно-лицевой области и шеи», раздел 1.2, с. 8", "re": "(?i:н)осогубн\\w+"}, "d:Резидуальная киста": {"t": "Резидуальная киста", "q": "Остаточная корневая киста, остающаяся после удаления или выпадения зуба; около 30% радикулярных кист являются резидуальными.", "book": "КР «Кисты челюстно-лицевой области и шеи», раздел 1.2, с. 6–7", "re": "(?i:р)езидуальн\\w+"}}};
